'use strict';
const KEY='gg-agroservicios-v1';const initial=()=>({jobs:[],workers:[{id:'w1',name:'Empleado 1',pct:4},{id:'w2',name:'Empleado 2',pct:4},{id:'w3',name:'Empleado 3',pct:4}],machines:[],hectares:[],fuelLoads:[],fuelUse:[],expenses:[],receipts:[],payments:[],maintenance:[],plans:[],quotes:[],inventory:[],alerts:[],radioChannels:[],radioDevices:[],maintenanceAlerts:[],fieldLocations:[],tires:[],rainfall:[]});
let db=initial();for(const [k,v] of Object.entries(initial()))if(!Array.isArray(db[k]))db[k]=v;
const MACHINE_TYPES={tractor:'🚜',cosechadora:'🌾',sembradora:'🌱',pulverizadora:'💦',fertilizadora:'🌿',tolva:'🚛',acoplado:'🚚',cisterna:'🛢️'};
if(!Array.isArray(db.machineDetails))db.machineDetails=[];if(!db.company||typeof db.company!=='object')db.company={};
function guessType(name){let n=String(name).toLowerCase();return n.includes('cosech')||n.includes('1175')||n.includes('1450')?'cosechadora':n.includes('sembr')||n.includes('pla')?'sembradora':n.includes('pulver')?'pulverizadora':n.includes('fertiliz')?'fertilizadora':n.includes('tolva')?'tolva':n.includes('acopl')?'acoplado':n.includes('cisterna')?'cisterna':'tractor'}
function machineInfo(name){return db.machineDetails.find(m=>m.name===name)||{name,type:guessType(name),color:'#247a36'}}
function machineChip(name){const m=machineInfo(name);return `<span style="display:inline-flex;align-items:center;gap:7px;padding:6px 10px;border-radius:12px;border-left:5px solid ${esc(m.color)};background:rgba(127,127,127,.1);margin:3px">${MACHINE_TYPES[m.type]||'🚜'} ${esc(name)}</span>`}
function machineManager(){return title('Mis maquinarias','Agregá, editá y asigná un color a cada equipo')+`<div class="card"><h3>Agregar maquinaria</h3><form data-form="machine">${field('Nombre / modelo','name')}${sel('Tipo de maquinaria','type',Object.keys(MACHINE_TYPES).map(t=>({id:t,name:MACHINE_TYPES[t]+' '+t.charAt(0).toUpperCase()+t.slice(1)})))}<label>Color del equipo</label><input type="color" name="color" value="#247a36" style="height:52px"><button type="submit">Agregar máquina</button></form></div>`+db.machines.map((name,i)=>{const m=machineInfo(name);return `<div class="card"><div class="row"><div>${machineChip(name)}<p class="muted">${esc(m.type)}</p></div><div class="flex">${button('Editar','editmachine:'+i)}${button('Eliminar','deletemachine:'+i)}</div></div></div>`}).join('')+(db.machines.length?'':'<p>Sin equipos cargados.</p>')}
function machineEdit(){const name=db.machines[Number(selected)];if(!name)return machineManager();const m=machineInfo(name);return title('Editar maquinaria')+`<div class="card"><form data-form="machineedit"><input type="hidden" name="old" value="${esc(name)}">${field('Nombre / modelo','name','text',name)}${sel('Tipo de maquinaria','type',Object.keys(MACHINE_TYPES).map(t=>({id:t,name:MACHINE_TYPES[t]+' '+t.charAt(0).toUpperCase()+t.slice(1)})),m.type)}<label>Color del equipo</label><input type="color" name="color" value="${esc(m.color)}" style="height:52px"><button type="submit">Guardar cambios</button></form></div>`}
let page='home',selected=null,jobTab='overview',lastMessage='';
const $=s=>document.querySelector(s), id=()=>String(Date.now())+Math.random().toString(36).slice(2,7), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=x=>Number(String(x??0).replace(',','.'))||0,money=x=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:2}).format(x),fmt=x=>new Intl.NumberFormat('es-AR',{maximumFractionDigits:2}).format(x),today=()=>new Date().toLocaleDateString('en-CA'),opts=(items,chosen)=>items.map(o=>`<option value="${esc(o.id??o)}" ${(o.id??o)===chosen?'selected':''}>${esc(o.name??o)}</option>`).join(''),field=(label,name,type='text',value='',required=true)=>`<label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'step="any" min="0"':''}>`,sel=(label,name,items,chosen)=>`<label>${label}</label><select name="${name}">${opts(items,chosen)}</select>`,button=(text,act,cl='secondary')=>`<button class="${cl}" data-action="${act}">${text}</button>`,job=id=>db.jobs.find(j=>j.id===id),jobName=id=>job(id)?.name||'Trabajo eliminado',worker=id=>db.workers.find(w=>w.id===id),workerName=id=>worker(id)?.name||'Empleado eliminado',arr=(key,id)=>db[key].filter(x=>x.jobId===id),sum=(a,key)=>a.reduce((s,x)=>s+num(x[key]),0),ha=j=>j.finalHa!==null&&j.finalHa!==undefined&&j.finalHa!==''?num(j.finalHa):sum(arr('hectares',j.id),'ha'),revenue=j=>ha(j)*num(j.price),vat=j=>revenue(j)*num(j.vat)/100,invoice=j=>revenue(j)+vat(j),received=j=>sum(arr('receipts',j.id),'amount'),fuelCost=j=>arr('fuelUse',j.id).reduce((s,x)=>s+(x.source==='client'?0:num(x.liters)*num(x.unitPrice)),0),fuelDeduction=j=>arr('fuelUse',j.id).reduce((s,x)=>s+(x.source==='client'&&x.deduct?num(x.liters)*num(x.unitPrice):0),0),balance=j=>invoice(j)-received(j)-fuelDeduction(j),jobExpenses=j=>sum(arr('expenses',j.id),'amount'),earnings=(j,wid)=>j.staff?.[wid]?revenue(j)*num(j.staff[wid])/100:0,staffCost=j=>db.workers.reduce((s,w)=>s+earnings(j,w.id),0),profit=j=>revenue(j)-fuelCost(j)-jobExpenses(j)-staffCost(j),fuelLoaded=()=>sum(db.fuelLoads,'liters'),fuelUsed=()=>sum(db.fuelUse.filter(x=>x.source!=='client'),'liters'),fuelAvailable=()=>fuelLoaded()-fuelUsed(),averageFuel=()=>fuelLoaded()>0?db.fuelLoads.reduce((s,x)=>s+num(x.liters)*num(x.price),0)/fuelLoaded():0,overallEarn=wid=>db.jobs.reduce((s,j)=>s+earnings(j,wid),0),paid=wid=>sum(db.payments.filter(p=>p.workerId===wid),'amount');
function save(){try{if(window.serviciosSave)window.serviciosSave(db);lastMessage='Guardado localmente; sincronización pendiente.'}catch(e){alert('No se pudo guardar. Exportá una copia de seguridad: '+e.message)}}function go(p){page=p;render()}function title(t,sub=''){return `<h2>${t}</h2>${sub?`<p class="muted">${esc(sub)}</p>`:''}`}function empty(t){return `<div class="card muted">${t}</div>`}function metric(label,value){return `<div class="card"><div class="muted">${label}</div><div class="stat">${value}</div></div>`}function action(text,fn){return `<button data-action="${fn}">${text}</button>`}function list(key,fn){return db[key].slice().reverse().map(fn).join('')||'<p class="muted">Todavía no hay registros.</p>'}function jobSelect(){return sel('Trabajo / campo','jobId',db.jobs.map(j=>({id:j.id,name:j.name+' — '+j.labor})),selected)}function dateInput(){return field('Fecha','date','date',today())}function recordLine(main,sub,amount,deleteType,recordId){return `<div class="listitem row"><div><b>${esc(main)}</b><div class="muted">${esc(sub)}</div></div><div style="text-align:right"><b>${esc(amount)}</b><br><button class="secondary tiny" data-delete="${deleteType}" data-id="${esc(recordId)}">Eliminar</button></div></div>`}
function home(){const rev=db.jobs.reduce((s,j)=>s+revenue(j),0),gain=db.jobs.reduce((s,j)=>s+profit(j),0)-sum(db.expenses.filter(x=>!x.jobId),'amount');return title('Panel principal')+`<div class="grid">${metric('Hectáreas',fmt(db.jobs.reduce((s,j)=>s+ha(j),0))+' ha')}${metric('Facturación sin IVA',money(rev))}${metric('Ganancia estimada',money(gain))}${metric('Pendiente de cobrar',money(db.jobs.reduce((s,j)=>s+balance(j),0)))}</div><h2>Accesos rápidos</h2><div class="actions">${action('＋ Nuevo trabajo','newjob')}${action('🌾 Hectáreas','hectares')}${action('⛽ Gasoil','fuel')}${action('🧾 Gastos','expenses')}${action('👥 Empleados','workers')}${action('💰 Cobros','receipts')}</div><h2>Trabajos</h2>${db.jobs.length?db.jobs.map(j=>`<div class="card row"><div><b>${esc(j.name)}</b><div class="muted">${esc(j.labor)} · ${fmt(ha(j))} ha</div><span class="pill">${j.status==='done'?'Terminado':'Activo'}</span></div><div class="flex">${button('Abrir','job:'+j.id)}${button('Eliminar','deletejob:'+j.id)}</div></div>`).join(''):empty('Creá tu primer trabajo para comenzar.')}<div class="notice">Los datos se guardan en este iPhone/navegador. Hacé copias de seguridad periódicas en «Más».</div>`}
function jobs(){return title('Mis trabajos')+`<p>${action('＋ Nuevo trabajo','newjob')}</p>`+(db.jobs.map(j=>`<div class="card"><div class="row"><div><h3>${esc(j.name)}</h3><div class="muted">${esc(j.client)} · ${esc(j.labor)}</div></div><span class="pill">${j.status==='done'?'Terminado':'Activo'}</span></div><p>${fmt(ha(j))} ha · ${money(revenue(j))} sin IVA</p><div class="flex">${button('Abrir','job:'+j.id)}${button('Editar','editjob:'+j.id)}${button('Informe A4','print:'+j.id)}${button('Eliminar','deletejob:'+j.id)}</div></div>`).join('')||empty('Sin trabajos todavía.'))}
function newJob(edit){const j=edit?job(edit):null;return title(j?'Editar trabajo':'Nuevo trabajo')+`<form data-form="job"><input type="hidden" name="id" value="${esc(j?.id||'')}">${field('Nombre del campo / trabajo','name','text',j?.name||'')}${field('Cliente','client','text',j?.client||'')}${field('Labor (cosecha, siembra, rolo...)','labor','text',j?.labor||'')}${dateInput()}${field('Hectáreas previstas del trabajo','plannedHa','number',j?.plannedHa??'',false)}${field('Precio por hectárea ($ ARS)','price','number',j?.price??'',false)}${sel('IVA (%)','vat',[{id:'0',name:'0%'},{id:'10.5',name:'10,5%'},{id:'21',name:'21%'}],String(j?.vat??'10.5'))}<label>Estado</label><select name="status"><option value="active" ${j?.status!=='done'?'selected':''}>Activo</option><option value="done" ${j?.status==='done'?'selected':''}>Terminado</option></select><h3>Empleados participantes y porcentaje</h3>${db.workers.map(w=>`<div class="card"><label><input style="width:auto" type="checkbox" name="staff_${esc(w.id)}" ${j?j.staff?.[w.id]!==undefined?'checked':'':'checked'}> ${esc(w.name)}</label>${field('Porcentaje de este trabajo (%)','pct_'+w.id,'number',j?.staff?.[w.id]??w.pct)}</div>`).join('')}<h3>Máquinas participantes</h3>${db.machines.map((m,i)=>`<label><input style="width:auto" type="checkbox" name="machine_${i}" ${j?.machines?.includes(m)?'checked':''}> ${machineChip(m)}</label>`).join('')}<button type="submit">Guardar trabajo</button></form>`}
function jobDetail(){const j=job(selected);if(!j)return jobs();const tabs=[['overview','Resumen'],['hectares','Hectáreas'],['staff','Personal'],['fueluse','Gasoil'],['expenses','Gastos'],['receipts','Cobros']];let out=`<div class="row"><div>${title(j.name,j.client+' · '+j.labor)}</div>${button('Editar','editjob:'+j.id)}</div><div class="tabs">${tabs.map(([k,t])=>`<button class="${jobTab===k?'active':''}" data-tab="${k}">${t}</button>`).join('')}</div>`;if(jobTab==='overview')out+=`<div class="grid">${metric('Hectáreas',fmt(ha(j))+' ha')}${metric('Facturación sin IVA',money(revenue(j)))}${metric('Ganancia estimada',money(profit(j)))}${metric('Saldo cliente',money(balance(j)))}</div><div class="card"><h3>Resultado del trabajo</h3>${line('Facturación sin IVA',revenue(j))}${line('IVA',vat(j))}${line('Total a cobrar',invoice(j))}<div class="line"></div>${line('Gasoil propio consumido',-fuelCost(j))}${line('Empleados devengados',-staffCost(j))}${line('Otros gastos',-jobExpenses(j))}<div class="line"></div>${line('Ganancia estimada sin IVA',profit(j))}${line('Gasoil a descontar (cliente)',-fuelDeduction(j))}${line('Cobrado',received(j))}${line('Pendiente de cobrar',balance(j))}</div><div class="card"><b>Máquinas</b><p>${(j.machines||[]).map(machineChip).join('')||'Sin asignar'}</p><b>Empleados</b><p>${db.workers.filter(w=>j.staff?.[w.id]!==undefined).map(w=>esc(w.name)+' ('+fmt(j.staff[w.id])+'%)').join(', ')||'Sin asignar'}</p></div>${action('🖨 Informe A4','print:'+j.id)}`;
if(jobTab==='hectares')out+=`<div class="card"><h3>Hectáreas previstas: ${fmt(j.plannedHa||0)} ha</h3><h3>Total final (opcional)</h3><p class="muted">Si cargás un total final, reemplaza la suma diaria para los cálculos. Las cargas diarias se conservan.</p><form data-form="finalha">${field('Hectáreas finales','finalHa','number',j.finalHa??'',false)}<button type="submit">Guardar total final</button></form></div><div class="card"><h3>Registrar hectáreas por día</h3><form data-form="hectares">${dateInput()}${field('Hectáreas realizadas','ha','number')}<button type="submit">Agregar jornada</button></form></div><div class="card"><h3>Historial</h3>${list('hectares',x=>x.jobId===j.id?recordLine(x.date,'Jornada',fmt(x.ha)+' ha','hectares',x.id):'')}</div>`;
if(jobTab==='staff')out+=`<div class="card"><h3>Personal asignado</h3>${db.workers.filter(w=>j.staff?.[w.id]!==undefined).map(w=>line(w.name+' ('+fmt(j.staff[w.id])+'%)',earnings(j,w.id))).join('')||'Sin empleados'}</div><p class="muted">Los pagos y adelantos se registran en Empleados y pueden asociarse a este campo o ser generales.</p>${action('Registrar pago / adelanto','payments')}`;
if(jobTab==='fueluse')out+=`<div class="card"><h3>Asignar consumo real</h3><p class="muted">Litros cargados sin asignar: ${fmt(fuelAvailable())} L. Precio promedio registrado: ${money(averageFuel())}/L.</p><form data-form="fueluse">${dateInput()}${field('Litros consumidos en este campo','liters','number')}${fuelSourceFields()}<button type="submit">Asignar consumo</button></form></div><div class="card">${arr('fuelUse',j.id).map(x=>recordLine(x.date,fmt(x.liters)+' L × '+money(x.unitPrice),money(x.liters*x.unitPrice)+(x.source==='client'?(x.deduct?' · Descuenta saldo':' · Cliente, sin descuento'):' · Propio'),'fuelUse',x.id)).join('')||'Sin consumo asignado'}</div>`;
if(jobTab==='expenses')out+=`<p>${action('＋ Nuevo gasto','expenses')}</p><div class="card">${arr('expenses',j.id).map(x=>recordLine(x.category,x.date+' · '+x.detail,money(x.amount),'expenses',x.id)).join('')||'Sin gastos'}</div>`;
if(jobTab==='receipts')out+=`<div class="card">${line('Total con IVA',invoice(j))}${line('Gasoil a descontar (cliente)',-fuelDeduction(j))}${line('Cobrado',received(j))}${line('Saldo pendiente',balance(j))}</div><p>${action('＋ Registrar cobro','receipts')}</p><div class="card">${arr('receipts',j.id).map(x=>recordLine(x.type,x.date+' · '+x.note,money(x.amount),'receipts',x.id)).join('')||'Sin cobros'}</div>`;return out}
function line(t,v){return `<div class="row listitem"><span>${esc(t)}</span><b>${money(v)}</b></div>`}
function workers(){return title('Empleados')+`<div class="card"><h3>Agregar empleado</h3><form data-form="newworker">${field('Nombre del empleado','name')}${field('Porcentaje predeterminado (%)','pct','number',4)}<button type="submit">Agregar empleado</button></form></div><p>${action('＋ Pago / adelanto','payments')}</p>`+db.workers.map(w=>`<div class="card"><h3>${esc(w.name)}</h3>${line('Ganado en trabajos',overallEarn(w.id))}${line('Pagos y adelantos',paid(w.id))}${line('Saldo pendiente',overallEarn(w.id)-paid(w.id))}<div class="flex">${button('Cambiar nombre / %','editworker:'+w.id)}${button('Ver pagos','payments')}${button('Eliminar empleado','deleteworker:'+w.id)}</div></div>`).join('')}
function editWorker(wid){const w=worker(wid);return title('Editar empleado')+`<form data-form="worker"><input name="id" type="hidden" value="${esc(w.id)}">${field('Nombre','name','text',w.name)}${field('Porcentaje predeterminado (%)','pct','number',w.pct)}<p class="muted">El porcentaje predeterminado se aplica a trabajos nuevos. No modifica los trabajos existentes.</p><button type="submit">Guardar</button></form>`}
function payments(){return title('Pagos y adelantos')+`<div class="card"><form data-form="payment">${sel('Empleado','workerId',db.workers)}${sel('Tipo','type',['Adelanto','Pago'])}${sel('Asignación','scope',[{id:'general',name:'General'},{id:'job',name:'Campo específico'}])}<div id="paymentJob">${db.jobs.length?jobSelect():'<p class="muted">No hay trabajos todavía.</p>'}</div>${dateInput()}${field('Importe ($)','amount','number')}<button type="submit">Guardar pago</button></form></div><div class="card"><h3>Historial</h3>${list('payments',x=>recordLine(workerName(x.workerId)+' · '+x.type,x.date+' · '+(x.jobId?jobName(x.jobId):'General'),money(x.amount),'payments',x.id))}</div>`}
function fuelSourceFields(){return sel('¿Quién pone el gasoil?','source',[{id:'owner',name:'Lo compro yo (gasto mío)'},{id:'client',name:'Lo pone el cliente'}])+sel('¿Se descuenta de lo que debe pagar el cliente?','deduct',[{id:'no',name:'No'},{id:'yes',name:'Sí, descontar del saldo'}])+field('Precio por litro del gasoil del cliente ($)','clientPrice','number',0,false)+'<p class="muted">Si lo ponés vos, se usa el costo promedio de tus cargas y no se descuenta al cliente. Si lo pone el cliente, indicá el precio por litro cuando corresponda descontarlo.</p>'}function fuel(){return title('Control de gasoil')+`<div class="grid">${metric('Cargado',fmt(fuelLoaded())+' L')}${metric('Asignado propio',fmt(fuelUsed())+' L')}${metric('Sin asignar',fmt(fuelAvailable())+' L')}${metric('Precio promedio',money(averageFuel())+'/L')}</div><div class="card"><h3>Nueva carga</h3><form data-form="fuelload">${dateInput()}${sel('Máquina','machine',db.machines)}${field('Litros cargados','liters','number')}${field('Precio por litro ($)','price','number')}<button type="submit">Guardar carga</button></form></div><div class="card"><h3>Asignar consumo a un campo</h3>${db.jobs.length?`<form data-form="fueluseglobal">${jobSelect()}${dateInput()}${field('Litros realmente consumidos','liters','number')}${fuelSourceFields()}<button type="submit">Asignar litros</button></form>`:'<p class="muted">Primero creá un trabajo.</p>'}</div><div class="card"><h3>Cargas registradas</h3>${list('fuelLoads',x=>recordLine(x.machine,x.date+' · '+fmt(x.liters)+' L',money(x.liters*x.price),'fuelLoads',x.id))}</div><div class="card"><h3>Consumos asignados</h3>${list('fuelUse',x=>recordLine(jobName(x.jobId),x.date+' · '+fmt(x.liters)+' L',money(x.liters*x.unitPrice)+(x.source==='client'?(x.deduct?' · Descuenta saldo':' · Cliente, sin descuento'):' · Propio'),'fuelUse',x.id))}</div><div class="notice">El costo por campo usa el precio promedio de las cargas en el momento de asignar el consumo. Podés corregir eliminando y volviendo a asignar. Los litros propios requieren cargas previas; el gasoil del cliente se registra aparte y no reduce tu stock.</div>`}
function expenses(){return title('Gastos y mercadería')+`<div class="card"><form data-form="expense">${sel('Tipo de gasto','scope',[{id:'general',name:'General de la empresa'},{id:'job',name:'De un campo'}])}<div id="expenseJob">${db.jobs.length?jobSelect():'<p class="muted">No hay campos disponibles.</p>'}</div>${sel('Categoría','category',['Comida','Mercadería','Repuestos','Reparaciones','Gomería','Otros'])}${dateInput()}${field('Descripción','detail','text','',false)}${field('Importe ($)','amount','number')}<button type="submit">Guardar gasto</button></form></div><div class="card"><h3>Historial</h3>${list('expenses',x=>recordLine(x.category,x.date+' · '+(x.jobId?jobName(x.jobId):'General')+' · '+x.detail,money(x.amount),'expenses',x.id))}</div>`}
function receipts(){return title('Facturación y cobros')+`<div class="card"><h3>Registrar cobro o adelanto</h3>${db.jobs.length?`<form data-form="receipt">${jobSelect()}${sel('Tipo','type',['Adelanto','Pago parcial','Pago final'])}${dateInput()}${field('Importe ($)','amount','number')}${field('Observación','note','text','',false)}<button type="submit">Guardar cobro</button></form>`:'<p class="muted">Primero creá un trabajo.</p>'}</div><div class="card"><h3>Saldos de clientes</h3>${db.jobs.map(j=>`<div class="listitem"><b>${esc(j.name)}</b>${line('Total con IVA',invoice(j))}${line('Gasoil a descontar (cliente)',-fuelDeduction(j))}${line('Cobrado',received(j))}${line('Gasoil a descontar',-fuelDeduction(j))}${line('Pendiente',balance(j))}</div>`).join('')||'Sin trabajos'}</div><div class="card"><h3>Historial</h3>${list('receipts',x=>recordLine(jobName(x.jobId)+' · '+x.type,x.date+' · '+x.note,money(x.amount),'receipts',x.id))}</div>`}
function accounts(){const clients=[...new Set(db.jobs.map(j=>j.client).filter(Boolean))];return title('Cuentas corrientes')+(clients.map(c=>{const jobs=db.jobs.filter(j=>j.client===c);return `<div class="card"><h3>${esc(c)}</h3>${line('Facturado con IVA',jobs.reduce((a,j)=>a+invoice(j),0))}${line('Cobros',jobs.reduce((a,j)=>a+received(j),0))}${line('Gasoil del cliente descontado',jobs.reduce((a,j)=>a+fuelDeduction(j),0))}${line('Saldo pendiente',jobs.reduce((a,j)=>a+balance(j),0))}<p class="muted">${jobs.map(j=>esc(j.name)+' ('+money(balance(j))+')').join(' · ')}</p></div>`}).join('')||empty('No hay clientes cargados.'))}
function liquidation(){return title('Liquidación de empleados','Importes calculados sobre facturación sin IVA.')+db.workers.map(w=>`<div class="card"><h3>${esc(w.name)}</h3>${line('Devengado',overallEarn(w.id))}${line('Pagos y adelantos',paid(w.id))}${line('Pendiente',overallEarn(w.id)-paid(w.id))}${button('🖨 Imprimir / Guardar PDF','liquidprint:'+w.id)}<h4>Detalle por trabajo</h4>${db.jobs.filter(j=>j.staff?.[w.id]!==undefined).map(j=>`<div class="listitem">${esc(j.name)} · ${fmt(j.staff[w.id])}% · ${money(earnings(j,w.id))}</div>`).join('')||'<p class="muted">Sin trabajos asignados.</p>'}</div>`).join('')}
function maintenance(){return title('Mantenimiento de máquinas')+`<div class="card"><form data-form="maintenance">${sel('Máquina','machine',db.machines)}${dateInput()}${field('Horas / kilometraje (opcional)','hours','number','',false)}${field('Tarea realizada o pendiente','detail')}${field('Costo ($)','amount','number',0,false)}<button type="submit">Guardar mantenimiento</button></form></div><div class="card"><h3>Historial</h3>${list('maintenance',x=>recordLine(x.machine,x.date+' · '+x.detail+(x.hours?' · '+x.hours+' h':''),money(x.amount),'maintenance',x.id))}</div>`}
function planning(){return title('Planificación de trabajos')+`<div class="card"><form data-form="plan">${field('Campo / cliente','name')}${field('Labor prevista','labor')}${field('Fecha prevista','date','date',today())}${sel('Máquina','machine',db.machines)}${field('Hectáreas estimadas','hectares','number','',false)}<button type="submit">Agendar trabajo</button></form></div><div class="card"><h3>Próximos trabajos</h3>${db.plans.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(x=>recordLine(x.name,x.date+' · '+x.labor+' · '+x.machine,fmt(x.hectares)+' ha','plans',x.id)).join('')||'<p class="muted">Sin trabajos programados.</p>'}</div>`}
function radioPanel(){const machineOptions=[{id:'',name:'Sin asignar'},...db.machines.map(x=>({id:x,name:x}))];const channelOptions=db.radioChannels.map(x=>({id:x.id,name:x.name+' · '+x.rx+' MHz'}));return title('📻 Centro de radios','Equipos, canales, códigos Q y guías sin internet')+`<div class="card"><h3>Agregar radio</h3><form data-form="radiodevice">${field('Marca','brand','text','Baofeng')}${field('Modelo','model','text','UV-5R')}${field('Nombre / identificador','alias','text','',false)}${sel('Máquina asignada','machine',machineOptions)}${field('Responsable / ubicación','operator','text','',false)}${field('Número de serie (opcional)','serial','text','',false)}<button type="submit">Guardar radio</button></form></div><div class="card"><h3>Mis radios (${db.radioDevices.length})</h3>${db.radioDevices.map(x=>{const linked=(x.channelIds||[]).map(cid=>db.radioChannels.find(c=>c.id===cid)).filter(Boolean);return `<div class="listitem"><b>📻 ${esc(x.brand||'')} ${esc(x.model||x.name||'Radio')}</b> ${x.alias?`· ${esc(x.alias)}`:''}<p class="muted">🚜 ${esc(x.machine||x.assigned||'Sin asignar')} · ${esc(x.operator||'Sin responsable')}${x.serial?' · Serie: '+esc(x.serial):''}</p><p class="muted">Canales: ${linked.length?linked.map(c=>esc(c.name)+' ('+esc(c.rx)+' MHz)').join(', '):'Ninguno vinculado'}</p><div class="flex">${button('Editar ficha / canales','radioedit:'+x.id)}<button class="secondary" data-delete="radioDevices" data-id="${esc(x.id)}">Eliminar</button></div></div>`}).join('')||'<p class="muted">Todavía no hay radios.</p>'}</div><div class="card"><h3>Guardar frecuencia / canal</h3><form data-form="radiochannel">${field('Nombre del canal','name')}${field('Frecuencia recepción MHz','rx','number')}${field('Frecuencia transmisión MHz','tx','number')}${field('Tono CTCSS / DCS (opcional)','tone','text','',false)}${field('Notas / uso','note','text','',false)}<button type="submit">Guardar canal</button></form><p class="muted">Guardar una frecuencia no autoriza a transmitir. Verificá bandas y permisos ENACOM.</p></div><div class="card"><h3>Canales guardados</h3>${list('radioChannels',x=>recordLine(x.name,x.rx+' MHz RX · '+x.tx+' MHz TX · '+(x.tone||'Sin tono')+' · '+(x.note||''),'📡','radioChannels',x.id))}</div><div class="card"><h3>Diccionario de códigos Q</h3>${[['QTH','Ubicación de la estación'],['QSL','Confirmación de recepción'],['QRM','Interferencia de otras estaciones'],['QRN','Interferencia atmosférica'],['QRV','Listo para comunicar'],['QSO','Comunicación entre estaciones'],['QRT','Dejar de transmitir'],['QSY','Cambiar de frecuencia'],['QRZ','¿Quién me llama?'],['QRP','Reducir potencia'],['QRO','Aumentar potencia'],['QRS','Transmitir más despacio']].map(([q,d])=>`<div class="listitem"><b>${q}</b> · ${d}</div>`).join('')}</div><div class="card"><h3>🔤 Alfabeto fonético internacional</h3><p class="muted">Para deletrear indicativos, nombres y mensajes por radio. Disponible sin internet.</p><details open><summary>Letras A–Z (OTAN / UIT)</summary><div class="listitem"><b>A</b> · Alfa</div><div class="listitem"><b>B</b> · Bravo</div><div class="listitem"><b>C</b> · Charlie</div><div class="listitem"><b>D</b> · Delta</div><div class="listitem"><b>E</b> · Echo</div><div class="listitem"><b>F</b> · Foxtrot</div><div class="listitem"><b>G</b> · Golf</div><div class="listitem"><b>H</b> · Hotel</div><div class="listitem"><b>I</b> · India</div><div class="listitem"><b>J</b> · Juliett</div><div class="listitem"><b>K</b> · Kilo</div><div class="listitem"><b>L</b> · Lima</div><div class="listitem"><b>M</b> · Mike</div><div class="listitem"><b>N</b> · November</div><div class="listitem"><b>O</b> · Oscar</div><div class="listitem"><b>P</b> · Papa</div><div class="listitem"><b>Q</b> · Quebec</div><div class="listitem"><b>R</b> · Romeo</div><div class="listitem"><b>S</b> · Sierra</div><div class="listitem"><b>T</b> · Tango</div><div class="listitem"><b>U</b> · Uniform</div><div class="listitem"><b>V</b> · Victor</div><div class="listitem"><b>W</b> · Whiskey</div><div class="listitem"><b>X</b> · X-ray</div><div class="listitem"><b>Y</b> · Yankee</div><div class="listitem"><b>Z</b> · Zulu</div></details><details><summary>Números 0–9 (forma habitual)</summary><div class="listitem"><b>0</b> · Zero</div><div class="listitem"><b>1</b> · One</div><div class="listitem"><b>2</b> · Two</div><div class="listitem"><b>3</b> · Three</div><div class="listitem"><b>4</b> · Four</div><div class="listitem"><b>5</b> · Five</div><div class="listitem"><b>6</b> · Six</div><div class="listitem"><b>7</b> · Seven</div><div class="listitem"><b>8</b> · Eight</div><div class="listitem"><b>9</b> · Nine</div></details><p class="muted">Ejemplo: G&G se deletrea Golf y Golf.</p></div><div class="card"><h3>Guías de programación</h3><details><summary>Baofeng UV-5R / UV-82</summary><p>En modo VFO, ingresá RX; configurá shift, offset y tonos según corresponda; guardá con MEM-CH en memoria libre. Verificá el manual de tu versión antes de transmitir.</p></details><details><summary>Yaesu base</summary><p>Consultá el manual específico: VFO / Memory, frecuencia, desplazamiento, tonos y guardar memoria. El procedimiento cambia según el modelo.</p></details><p class="muted">Esta aplicación no transmite ni controla las radios.</p></div>`}
function radioEdit(){const x=db.radioDevices.find(r=>r.id===selected);if(!x)return radioPanel();const machineOptions=[{id:'',name:'Sin asignar'},...db.machines.map(m=>({id:m,name:m}))];return title('Editar ficha de radio')+`<div class="card"><form data-form="radioedit"><input type="hidden" name="id" value="${esc(x.id)}">${field('Marca','brand','text',x.brand||'')}${field('Modelo','model','text',x.model||x.name||'')}${field('Identificador','alias','text',x.alias||'',false)}${sel('Máquina asignada','machine',machineOptions,x.machine||x.assigned||'')}${field('Responsable / ubicación','operator','text',x.operator||'',false)}${field('Número de serie','serial','text',x.serial||'',false)}<h3>Canales programados en este equipo</h3>${db.radioChannels.length?db.radioChannels.map(c=>`<label style="display:flex;align-items:center;gap:10px"><input type="checkbox" name="channel_${esc(c.id)}" ${(x.channelIds||[]).includes(c.id)?'checked':''}>${esc(c.name)} · ${esc(c.rx)} MHz</label>`).join(''):'<p class="muted">Primero agregá canales desde Centro de radios.</p>'}<button type="submit">Guardar cambios</button></form></div><p>${button('← Volver a radios','radios')}</p>`}

function liquidationPrint(wid){const w=worker(wid);if(!w)return;const rows=db.jobs.filter(j=>j.staff?.[wid]!==undefined).map(j=>`<tr><td>${esc(j.name)}</td><td>${fmt(ha(j))}</td><td>${fmt(j.staff[wid])}%</td><td>${money(earnings(j,wid))}</td></tr>`).join('');const html=`<h1>Liquidación · ${esc(w.name)}</h1><p>Emitido: ${today()} · Importes sin IVA</p><table border="1" cellpadding="8" cellspacing="0" width="100%"><tr><th>Trabajo</th><th>Ha</th><th>%</th><th>Devengado</th></tr>${rows}</table><h3>Devengado: ${money(overallEarn(wid))}</h3><h3>Pagos y adelantos: ${money(paid(wid))}</h3><h2>Saldo: ${money(overallEarn(wid)-paid(wid))}</h2><p>Detalle de pagos:</p>${db.payments.filter(x=>x.workerId===wid).map(x=>`<p>${esc(x.date)} · ${esc(x.type)} · ${money(x.amount)}</p>`).join('')}`;const area=$('#printArea');area.innerHTML=html;area.classList.remove('hide');window.print();setTimeout(()=>area.classList.add('hide'),500)}
function appearancePanel(){return title('🎨 Personalización')+`<div class="card"><h3>🎨 Personalización</h3><p>Tocá un color para cambiar el encabezado, los botones y el menú. Se guarda automáticamente en este dispositivo.</p><div class="color-settings">${Object.entries(window.serviciosPalette).map(([name,color])=>`<button type="button" class="color-choice ${window.getServiciosColor()===color?'selected':''}" style="--swatch:${color};background-color:${color}" data-color="${color}" title="${name}" aria-label="Color ${name}"></button>`).join('')}</div><label>Color personalizado</label><input id="customAccent" type="color" value="${window.getServiciosColor()}" aria-label="Elegir color personalizado"><p class="muted" id="accentStatus">Color actual: ${window.getServiciosColor()}</p></div>`}
function more(){return title('Herramientas y respaldos')+`<div class="card"><h3>🧭 Gestión</h3><div class="actions">${action('💳 Cuentas corrientes','accounts')}${action('👥 Liquidación de empleados','liquidation')}${action('📻 Centro de radios','radios')}${action('🛠️ Historial de mantenimiento','maintenance')}${action('🔧 Alertas de mantenimiento','maintalerts')}${action('📍 Ubicación de campos','locations')}${action('🏢 Datos de empresa','companysettings')}${action('💾 Copias de seguridad','backups')}${action('📅 Planificación','planning')}${action('📄 Presupuestos PDF','quotes')}${action('📦 Inventario de repuestos','inventory')}${action('⏰ Alertas y vencimientos','alerts')}${action('🧮 Herramientas agrícolas','agtools')}${action('🎨 Personalización','appearance')}${action('🚜 Maquinarias','machines')}${action('🛞 Control de neumáticos','tires')}${action('🌧️ Registro de lluvias','rainfall')}${action('📊 Estadísticas gráficas','statistics')}${action('📏 Conversor de medidas','measureconvert')}${action('🧭 Brújula','compass')}${action('☀️ Electricidad 12 V y solar','solar12')}${action('📐 Sistema métrico decimal','metricdecimal')}</div></div><div class="card"><h3>💾 Informes y archivos</h3><div class="flex">${button('Descargar copia JSON','backup')}${button('Importar copia JSON','restore')}${button('Exportar CSV','csv')}</div><input type="file" id="restoreFile" accept=".json,application/json" class="hide"><p class="muted">La copia JSON guarda todos los registros. El CSV es compatible con Excel y Numbers.</p></div><div class="card"><h3>🖨️ Imprimir informes A4</h3>${db.jobs.map(j=>`<p>${button('Informe: '+esc(j.name),'print:'+j.id)}</p>`).join('')||'<p class="muted">Creá un trabajo primero.</p>'}${button('Informe general','printall')}</div><div class="notice"><b>Importante:</b> el almacenamiento del iPhone puede borrarse al eliminar datos del navegador o la app. Exportá una copia JSON después de cada jornada importante y guardala en Archivos/iCloud.</div>`}

function quotes(){return title('Presupuestos','Encabezado personalizable en cada presupuesto · importes en pesos argentinos')+`<div class="card"><h3>Nuevo presupuesto</h3><form data-form="quote">${field('Nombre del emisor (encabezado PDF)','issuer','text','G&G Agroservicios')}${field('Cliente','client')}${field('Campo','field','text','',false)}${field('Servicio / labor','labor')}${field('Fecha','date','date',today())}${field('Válido hasta','expiry','date',today())}${field('Hectáreas estimadas','hectares','number')}${field('Precio por hectárea ($ ARS)','price','number')}${sel('IVA','vat',[{id:'0',name:'0%'},{id:'10.5',name:'10,5%'},{id:'21',name:'21%'}],'10.5')}<label>Observaciones</label><textarea name="notes"></textarea><button type="submit">Guardar presupuesto</button></form></div><div class="card"><h3>Presupuestos guardados</h3>${db.quotes.slice().reverse().map(q=>`<div class="listitem"><b>${esc(q.client)}</b> · ${esc(q.field)}<p class="muted">${esc(q.labor)} · Vence ${esc(q.expiry)} · ${esc(q.status)}</p><p><b>${money(q.hectares*q.price*(1+q.vat/100))}</b></p><div class="flex">${button('Ver / guardar PDF','quoteprint:'+q.id)}${button('Convertir en trabajo','quotework:'+q.id)}<button class="secondary" data-delete="quotes" data-id="${esc(q.id)}">Eliminar</button></div></div>`).join('')||'<p class="muted">Sin presupuestos.</p>'}</div><div class="notice">Para crear el PDF en iPhone, tocá «Ver / guardar PDF» y elegí Guardar en Archivos desde la vista de impresión.</div>`}
function printQuote(qid){const q=db.quotes.find(x=>x.id===qid);if(!q)return;const base=q.hectares*q.price,iva=base*q.vat/100;$('#printArea').innerHTML=`<h1>${esc(q.issuer)}</h1><h2>PRESUPUESTO</h2><p>Fecha: ${esc(q.date)} · Válido hasta: ${esc(q.expiry)}</p><hr><p><b>Cliente:</b> ${esc(q.client)}</p><p><b>Campo:</b> ${esc(q.field)}</p><p><b>Servicio:</b> ${esc(q.labor)}</p><table style="width:100%;border-collapse:collapse"><tr><th>Hectáreas</th><th>Precio / ha</th><th>Subtotal</th></tr><tr><td>${fmt(q.hectares)}</td><td>${money(q.price)}</td><td>${money(base)}</td></tr></table><hr><p>Subtotal: ${money(base)}</p><p>IVA ${q.vat}%: ${money(iva)}</p><h2>Total: ${money(base+iva)}</h2><p>${esc(q.notes)}</p><small>Presupuesto expresado en pesos argentinos (ARS).</small>`;window.print()}
function quoteToJob(qid){const q=db.quotes.find(x=>x.id===qid);if(!q)return;if(!confirm('¿Crear un trabajo con los datos de este presupuesto?'))return;const j={id:id(),name:q.field||q.labor,client:q.client,labor:q.labor,date:today(),plannedHa:q.hectares,finalHa:null,price:q.price,vat:q.vat,status:'active',staff:{},machines:[]};db.jobs.push(j);q.status='Convertido a trabajo';selected=j.id;jobTab='overview';page='job';save();render()}
function inventory(){const units=x=>x.unit||'unidades';return title('Inventario de repuestos y lubricantes')+`<div class="card"><h3>Agregar producto</h3><form data-form="item">${sel('Categoría','category',[{id:'Repuesto',name:'Repuesto'},{id:'Aceite',name:'Aceite'},{id:'Grasa',name:'Grasa'}])}${field('Nombre / tipo (ej. aceite 15W40)','name')}${field('Código','code','text','',false)}${field('Máquina asociada','machine','text','',false)}${field('Proveedor','supplier','text','',false)}${field('Cantidad disponible','qty','number',0)}${field('Stock mínimo','min','number',0)}${field('Costo por unidad de medida ($)','cost','number',0)}<p class="muted">Aceites en litros (L), grasas en kilogramos (kg), repuestos en unidades. Se aceptan cantidades decimales.</p><button type="submit">Guardar producto</button></form></div><div class="card"><h3>Existencias</h3>${db.inventory.map(x=>`<div class="listitem"><b>${esc(x.name)}</b> <span class="pill">${esc(x.category||'Repuesto')}</span> ${num(x.qty)<=num(x.min)?'<span class="pill">Stock bajo</span>':''}<p class="muted">${esc(x.code)} · ${esc(x.machine)} · ${esc(x.supplier)}</p><p>${fmt(x.qty)} ${esc(units(x))} · ${money(x.cost)} / ${esc(units(x))} · Valor: ${money(num(x.qty)*num(x.cost))}</p><div class="flex">${button('Registrar consumo','stock:'+x.id)}<button class="secondary" data-delete="inventory" data-id="${esc(x.id)}">Eliminar</button></div></div>`).join('')||'<p class="muted">Sin productos cargados.</p>'}</div>`}
function stockuse(){const x=db.inventory.find(x=>x.id===selected);if(!x)return inventory();return title('Registrar consumo',x.name+' · Disponible: '+fmt(x.qty)+' '+(x.unit||'unidades'))+`<div class="card"><form data-form="stockuse"><input type="hidden" name="id" value="${esc(x.id)}">${field('Cantidad consumida ('+(x.unit||'unidades')+')','qty','number',1)}${sel('Máquina (opcional)','machine',[{id:'',name:'Sin asignar'},...db.machines.map(m=>({id:m,name:m}))])}${field('Detalle de mantenimiento (opcional)','detail','text','',false)}<button type="submit">Descontar del inventario</button></form></div>`}
function alerts(){const now=today(),next=new Date();next.setDate(next.getDate()+7);const soon=next.toLocaleDateString('en-CA');const alerts=[];for(const q of db.quotes)if(q.status==='Pendiente'&&q.expiry<=soon)alerts.push({date:q.expiry,text:'Presupuesto '+q.client+' · '+(q.expiry<now?'Vencido':'Próximo a vencer')});for(const x of db.inventory)if(num(x.qty)<=num(x.min))alerts.push({date:now,text:'Stock bajo: '+x.name+' ('+fmt(x.qty)+')'});for(const x of db.alerts)if(x.date<=soon)alerts.push({date:x.date,text:x.detail});for(const j of db.jobs)if(j.status!=='done'&&balance(j)>0&&j.date<now)alerts.push({date:j.date,text:'Saldo pendiente (sin vencimiento definido): '+j.client+' · '+money(balance(j))});return title('Alertas y vencimientos','Avisos visibles al abrir la aplicación; no son notificaciones push')+`<div class="card"><h3>Agregar recordatorio</h3><form data-form="alert">${field('Descripción','detail')}${field('Fecha límite','date','date',today())}<button type="submit">Guardar alerta</button></form></div><div class="card"><h3>Alertas actuales</h3>${alerts.sort((a,b)=>a.date.localeCompare(b.date)).map(x=>`<div class="listitem"><b>${esc(x.text)}</b><p class="muted">${esc(x.date)}</p></div>`).join('')||'<p class="muted">No hay alertas próximas.</p>'}</div><div class="card"><h3>Recordatorios registrados</h3>${list('alerts',x=>recordLine(x.detail,x.date,'','alerts',x.id))}</div>`}

function agtools(){return title('Herramientas agrícolas','Calculadoras disponibles sin internet. Dólar y clima requieren conexión; el gasoil común se guarda para usar sin internet.')+`<div class="card"><h3>🧮 Calculadora</h3><div class="grid">${field('Número A','calcA','number',0)}${field('Número B','calcB','number',0)}</div><label>Operación</label><select id="calcOp"><option value="+">Sumar</option><option value="-">Restar</option><option value="*">Multiplicar</option><option value="/">Dividir</option><option value="%">Porcentaje de A (B%)</option></select><p><button type="button" onclick="agCalc()">Calcular</button></p><h3 id="calcResult">Resultado: —</h3></div>
<div class="card"><h3>🚜 Capacidad de trabajo</h3><div class="grid">${field('Ancho de labor (metros)','agWidth','number',13)}${field('Velocidad (km/h)','agSpeed','number',7)}${field('Horas de jornada','agHours','number',24)}${field('Eficiencia (%)','agEfficiency','number',75)}${field('Superficie objetivo (ha)','agTarget','number',2500)}</div><button type="button" onclick="agCapacity()">Calcular hectáreas</button><div id="agCapacityResult" class="notice" style="margin-top:12px">Completá los datos y calculá.</div></div>
<div class="card"><h3>🌱 Calculadora de siembra</h3><div class="grid">${field('Distancia entre surcos (cm)','seedRows','number',52)}${field('Granos por metro','seedMeter','number',4)}${field('Germinación (%)','seedGerm','number',90)}${field('Peso de 1000 semillas (g)','seedWeight','number',300)}${field('Superficie a sembrar (ha)','seedHa','number',100)}</div><button type="button" onclick="agSeeds()">Calcular siembra</button><div id="seedResult" class="notice" style="margin-top:12px">Podés modificar todos los valores.</div></div>
<div class="card"><h3>💵 Dólar argentino</h3><p class="muted">Cotizaciones indicativas. Se actualizan solamente con internet y se indica cuándo fueron consultadas.</p><button type="button" onclick="agDollar()">Actualizar dólar</button><div id="dollarResult" class="notice" style="margin-top:12px">Sin consulta reciente.</div></div>
<div class="card"><h3>⛽ Gasoil común por estación</h3><p class="muted">Elegí la localidad para consultar los precios publicados por estación, sin promedios ni carga manual. La consulta se abre en la fuente externa y requiere internet.</p><label>Localidad</label><select id="dieselTown"><option value="quimili">Quimilí</option><option value="santiago-del-estero">Santiago del Estero (capital)</option><option value="la-banda">La Banda</option><option value="fernandez">Fernández</option><option value="anatuya">Añatuya</option></select><p><button type="button" onclick="agDieselOpen()">Ver precios por estación</button></p><div id="dieselResult" class="notice">Los valores dependen de la última publicación de cada estación. Verificá fecha y tipo de combustible (gasoil común / grado 2).</div></div>
<div class="card"><h3>🌧️ Clima y lluvias</h3>${field('Localidad','weatherTown','text','Quimilí')}<p class="muted">Pronóstico de lluvia para los próximos 3 días. Requiere internet para actualizar.</p><button type="button" onclick="agWeather()">Consultar pronóstico</button><div id="weatherResult" class="notice" style="margin-top:12px">Sin consulta reciente.</div></div>`}
function agDieselShow(){const town=document.getElementById('dieselTown');if(town)town.value=localStorage.getItem('servicios-diesel-town')||'quimili'}
function agDieselOpen(){const town=document.getElementById('dieselTown');if(!town)return;localStorage.setItem('servicios-diesel-town',town.value);const slug=town.value;const url='https://combustibles.ar/precios/santiago-del-estero/localidad/'+encodeURIComponent(slug);window.open(url,'_blank','noopener,noreferrer')}
function agVal(name){return Math.max(0,num(document.querySelector('[name="'+name+'"]')?.value))}
function agFmt(v){return Number.isFinite(v)?fmt(v):'—'}
function agCalc(){let a=num(document.querySelector('[name=calcA]').value),b=num(document.querySelector('[name=calcB]').value),o=document.getElementById('calcOp').value,r=o==='+'?a+b:o==='-'?a-b:o==='*'?a*b:o==='/'?(b?a/b:NaN):a*b/100;document.getElementById('calcResult').textContent='Resultado: '+agFmt(r)}
function agCapacity(){let w=agVal('agWidth'),v=agVal('agSpeed'),h=agVal('agHours'),e=Math.min(100,agVal('agEfficiency')),t=agVal('agTarget'),hour=w*v/10*e/100,day=hour*h;document.getElementById('agCapacityResult').innerHTML=`<b>${agFmt(day)} ha/día</b><p>${agFmt(hour)} ha/h de jornada · ${agFmt(h*e/100)} horas efectivas/día</p><p>${day?agFmt(t/day)+' días para '+agFmt(t)+' ha':'Ingresá ancho, velocidad, horas y eficiencia mayores que cero.'}</p>`}
function agSeeds(){let rows=agVal('seedRows'),m=agVal('seedMeter'),g=Math.min(100,agVal('seedGerm')),weight=agVal('seedWeight'),ha=agVal('seedHa'),population=rows?m*1000000/rows:0,plants=population*g/100,kg=population*weight/1000000;document.getElementById('seedResult').innerHTML=`<b>${agFmt(population)} semillas/ha</b><p>${agFmt(plants)} plantas esperadas/ha · ${m?agFmt(100/m)+' cm entre semillas':'—'}</p><p>${agFmt(kg)} kg/ha · ${agFmt(kg*ha)} kg para ${agFmt(ha)} ha</p><p class="muted">Estimación teórica: no contempla pérdidas adicionales de emergencia ni calibración.</p>`}
async function agDollar(){let el=document.getElementById('dollarResult');el.textContent='Consultando…';try{let r=await fetch('https://dolarapi.com/v1/dolares',{cache:'no-store'});if(!r.ok)throw Error('Sin respuesta');let data=await r.json(),types=['oficial','blue','bolsa'],rows=types.map(t=>data.find(x=>x.casa===t)).filter(Boolean);if(!rows.length)throw Error('Sin cotizaciones');let stamp=new Date().toLocaleString('es-AR');let html=rows.map(x=>`<p><b>${esc(x.nombre)}</b>: compra ${money(x.compra)} · venta ${money(x.venta)}</p>`).join('')+`<p class="muted">Consultado: ${stamp}. Fuente: DolarAPI. Valores orientativos.</p>`;el.innerHTML=html;localStorage.setItem('servicios-last-dollar',html)}catch(e){el.innerHTML=localStorage.getItem('servicios-last-dollar')||'No hay conexión ni cotización guardada.'}}
async function agWeather(){let el=document.getElementById('weatherResult');el.textContent='Consultando…';try{let town=document.querySelector('[name=weatherTown]').value.trim()||'Quimilí';let geo=await(await fetch('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(town)+'&count=1&language=es&format=json')).json();let loc=geo.results?.[0];if(!loc)throw Error('Localidad no encontrada');let url=`https://api.open-meteo.com/v1/forecast?latitude=${loc.latitude}&longitude=${loc.longitude}&daily=precipitation_sum,precipitation_probability_max&timezone=auto&forecast_days=3`;let res=await fetch(url),data=await res.json();if(!res.ok||!data.daily)throw Error('Pronóstico no disponible');let html=`<b>${esc(loc.name)}${loc.admin1?', '+esc(loc.admin1):''}</b>`+data.daily.time.map((d,i)=>`<p>${esc(d)}: ${agFmt(data.daily.precipitation_sum[i])} mm previstos · ${agFmt(data.daily.precipitation_probability_max[i])}% prob. lluvia</p>`).join('')+`<p class="muted">Actualizado ${new Date().toLocaleString('es-AR')}. Fuente: Open-Meteo. Pronóstico, no lluvia medida.</p>`;el.innerHTML=html;localStorage.setItem('servicios-last-weather',html)}catch(e){el.innerHTML=localStorage.getItem('servicios-last-weather')||('No se pudo actualizar: '+esc(e.message))}}

function v15Panel(){return title("⚙️ Administración", "Elegí una sección")+`<div class="actions">${action("🔧 Mantenimiento", "maintalerts")}${action("📍 Ubicación de campos", "locations")}${action("🏢 Datos de empresa", "companysettings")}${action("💾 Copias de seguridad", "backups")}</div>`}
function maintenanceAlertsPanel(){const due=db.maintenanceAlerts.filter(a=>(num(a.nextHours)>0&&num(a.currentHours)>=num(a.nextHours))||(a.dueDate&&a.dueDate<=today()));return title("🔧 Alertas de mantenimiento")+`<div class="card"><h3>🔧 Alertas de mantenimiento</h3><form data-form="maintenancealert">${sel('Maquinaria','machine',db.machines)}${field('Descripción','detail')}${field('Horas actuales del equipo','currentHours','number',0,false)}${field('Avisar a las horas','nextHours','number',0,false)}${field('O fecha límite','dueDate','date','',false)}<button>Guardar alerta</button></form>${db.maintenanceAlerts.map(a=>`<div class="listitem row"><div><b>${esc(a.machine)}</b> · ${esc(a.detail)}<div class="muted">Actual: ${fmt(a.currentHours)} h · Próximo: ${fmt(a.nextHours)} h · ${esc(a.dueDate||'Sin fecha')}</div>${(num(a.nextHours)>0&&num(a.currentHours)>=num(a.nextHours))||(a.dueDate&&a.dueDate<=today())?'<b style="color:#c22">⚠️ Vencida</b>':''}</div>${button('Eliminar','removealert:'+a.id)}</div>`).join('')}</div>`}
function locationsPanel(){return title("📍 Ubicación de campos")+`<div class="card"><h3>📍 Ubicación de campos</h3><form data-form="fieldlocation">${field('Nombre del campo','name')}${field('Latitud (ej. -27.65)','lat','number','',false)}${field('Longitud (ej. -62.42)','lng','number','',false)}${field('Dirección o referencia','address','text','',false)}<button>Guardar campo</button></form><p class="muted">Podés copiar las coordenadas desde Google Maps. Los enlaces requieren internet.</p>${db.fieldLocations.map(x=>`<div class="listitem row"><div><b>${esc(x.name)}</b><div class="muted">${esc(x.address||'')} · ${x.lat}, ${x.lng}</div><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(x.lat+','+x.lng)}">Abrir en Maps</a></div>${button('Eliminar','removelocation:'+x.id)}</div>`).join('')}</div>`}
function companyPanel(){return title("🏢 Datos de empresa")+`<div class="card"><h3>🏢 Personalización comercial</h3><form data-form="company">${field('Nombre de la empresa','name','text',db.company.name||'',false)}${field('Titular / responsable','owner','text',db.company.owner||'',false)}${field('CUIT','cuit','text',db.company.cuit||'',false)}${field('Teléfono','phone','text',db.company.phone||'',false)}${field('Localidad','city','text',db.company.city||'',false)}${field('Dirección','address','text',db.company.address||'',false)}<button>Guardar datos comerciales</button></form><p class="muted">Estos datos se guardan en este dispositivo y se incluyen en la copia JSON.</p></div>`}
function backupsPanel(){return title("💾 Copias de seguridad")+`<div class="card"><h3>💾 Copias de seguridad</h3>${button('Descargar copia completa JSON','backup')} ${button('Restaurar copia JSON','restore')}<p class="muted">Guardá el archivo en Archivos o iCloud. Restaurar reemplaza todos los datos actuales.</p></div><input type="file" id="restoreFile" accept=".json,application/json" class="hide">`}


function tiresPanel(){return title('🛞 Control de neumáticos','Historial por equipo, posición y horas de uso')+tirePressurePanel()+`<div class="card"><h3>Registrar neumático</h3><form data-form="tire">${sel('Maquinaria','machine',db.machines)}${field('Posición (ej. delantero izquierdo)','position')}${field('Medida (ej. 18.4-30)','size','text','',false)}${field('Marca / modelo','brand','text','',false)}${field('Fecha de instalación','installed','date',today())}${field('Horas de motor al instalar','startHours','number',0,false)}${field('Horas actuales del equipo','currentHours','number',0,false)}${field('Costo de compra ($)','cost','number',0,false)}${field('Observaciones / reparaciones','notes','text','',false)}<button>Guardar neumático</button></form></div><div class="card"><h3>Neumáticos registrados</h3>${db.tires.map(x=>`<div class="listitem"><b>🛞 ${esc(x.machine)} · ${esc(x.position)}</b><p>${esc(x.size)} · ${esc(x.brand)}</p><p class="muted">Instalado: ${esc(x.installed)} · Uso: ${fmt(Math.max(0,num(x.currentHours)-num(x.startHours)))} h · Costo: ${money(x.cost)}</p><p>${esc(x.notes)}</p>${button('Eliminar','deletetire:'+x.id)}</div>`).join('')||'<p class="muted">Sin neumáticos registrados.</p>'}</div>`}
function rainfallPanel(){const records=db.rainfall.slice().sort((a,b)=>b.date.localeCompare(a.date));return title('🌧️ Registro de lluvias','Milímetros por campo y fecha, disponible sin internet')+`<div class="card"><h3>Agregar lluvia</h3><form data-form="rain">${field('Campo / lugar','field')}${field('Fecha','date','date',today())}${field('Precipitación (mm)','mm','number')}${field('Observaciones','notes','text','',false)}<button>Guardar lluvia</button></form></div><div class="grid">${metric('Registros',db.rainfall.length)}${metric('Total registrado',fmt(db.rainfall.reduce((a,x)=>a+num(x.mm),0))+' mm')}</div><div class="card"><h3>Historial</h3><p class="muted">El total suma registros de distintos campos; consultá cada campo para evaluar su lluvia acumulada.</p>${records.map(x=>`<div class="listitem row"><div><b>${esc(x.field)} · ${fmt(x.mm)} mm</b><p class="muted">${esc(x.date)} · ${esc(x.notes)}</p></div>${button('Eliminar','deleterain:'+x.id)}</div>`).join('')||'<p class="muted">Todavía no hay registros.</p>'}</div>`}
function statisticsPanel(){const months={};const add=(date,key,v)=>{const m=String(date||'').slice(0,7);if(!/^\d{4}-\d{2}$/.test(m))return;months[m]??={ha:0,revenue:0,expenses:0,rain:0};months[m][key]+=num(v)};for(const h of db.hectares)add(h.date,'ha',h.ha);for(const j of db.jobs){const hs=db.hectares.filter(h=>h.jobId===j.id);if(!hs.length&&num(j.finalHa)>0)add(j.date,'ha',j.finalHa);add(j.date,'revenue',revenue(j))}for(const x of db.expenses)add(x.date,'expenses',x.amount);for(const x of db.rainfall)add(x.date,'rain',x.mm);const keys=Object.keys(months).sort().slice(-12);const chart=(key,label,color,unit)=>{const max=Math.max(1,...keys.map(k=>months[k][key]));return `<div class="card"><h3>${label}</h3>${keys.map(k=>`<div style="margin:10px 0"><div class="row"><span>${esc(k)}</span><b>${fmt(months[k][key])} ${unit}</b></div><div style="background:rgba(128,128,128,.2);height:15px;border-radius:8px;overflow:hidden"><div style="width:${Math.max(0,Math.min(100,months[k][key]/max*100))}%;background:${color};height:100%"></div></div></div>`).join('')||'<p class="muted">Sin datos para graficar.</p>'}</div>`};return title('📊 Estadísticas gráficas','Comparativos mensuales basados en tus registros')+chart('ha','Hectáreas trabajadas','#369c5c','ha')+chart('revenue','Facturación sin IVA','#3676bb','$')+chart('expenses','Gastos registrados','#d58c29','$')+chart('rain','Lluvias registradas (suma de campos)','#678bde','mm')+`<p class="muted">La facturación se agrupa por fecha del trabajo, no por fecha de cobro. La lluvia combina todos los campos registrados.</p>`}


// Paneles auxiliares: definidos antes de renderizar para evitar ReferenceError.
function measurePanel(){return title('📏 Conversor de medidas')+`<div class="card"><p>Convertí longitudes con el sistema métrico decimal.</p>${button('Abrir conversor métrico','metricdecimal')}</div>`}
function compassPanel(){return title('🧭 Brújula')+`<div class="card"><p>Para orientarte en el campo, utilizá la aplicación Brújula del teléfono.</p><p class="muted">La orientación por sensores no está habilitada en esta versión web.</p></div>`}
function solarPanel(){return title('☀️ Electricidad 12 V y solar')+`<div class="card"><h3>Cálculo básico de potencia</h3><label>Voltaje (V)</label><input type="number" id="solarVolts" value="12" step="any" oninput="updateSolarPanel()"><label>Corriente (A)</label><input type="number" id="solarAmps" value="1" step="any" oninput="updateSolarPanel()"><div id="solarResult" class="notice">12 W</div><p class="muted">Potencia (W) = voltaje (V) × corriente (A). Cálculo orientativo.</p></div>`}
function updateSolarPanel(){const a=document.getElementById('solarVolts'),b=document.getElementById('solarAmps'),r=document.getElementById('solarResult');if(a&&b&&r)r.textContent=(Number(a.value)*Number(b.value)).toLocaleString('es-AR')+' W'}
function render(){let html={home,jobs,v15:v15Panel,maintalerts:maintenanceAlertsPanel,locations:locationsPanel,companysettings:companyPanel,backups:backupsPanel,tires:tiresPanel,rainfall:rainfallPanel,statistics:statisticsPanel,measureconvert:measurePanel,compass:compassPanel,solar12:solarPanel,metricdecimal:metricDecimalPanel,newjob:()=>newJob(),editjob:()=>newJob(selected),job:jobDetail,workers,editworker:()=>editWorker(selected),payments,fuel,expenses,receipts,more,appearance:appearancePanel,machines:machineManager,editmachine:machineEdit,accounts,liquidation,radios:radioPanel,radioedit:radioEdit,maintenance,planning,quotes,inventory,stockuse,alerts,agtools}[page]?.()||home();$('#app').innerHTML=html;if(page==='agtools')agDieselShow();if(page==='measureconvert')updateMeasure();if(page==='metricdecimal')updateMetricDecimal();if(page==='solar12')updateSolarPanel();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.nav===page));for(const name of ['payment','expense']){let f=$(`form[data-form=${name}]`);if(f){const change=()=>{const el=$(`#${name==='payment'?'paymentJob':'expenseJob'}`);if(el)el.classList.toggle('hide',f.elements.scope.value!=='job')};f.elements.scope.addEventListener('change',change);change()}}}
function addRecord(key,record){db[key].push({id:id(),...record});save();render()}
function validateAmount(v,label){if(!Number.isFinite(v)||v<=0)throw Error(label+' debe ser mayor a cero')}
document.addEventListener('click',e=>{const n=e.target.closest('[data-nav],[data-action],[data-tab],[data-delete]');if(!n)return;if(n.dataset.nav){go(n.dataset.nav);return}if(n.dataset.tab){jobTab=n.dataset.tab;render();return}if(n.dataset.delete){if(confirm('¿Eliminar este registro?')){db[n.dataset.delete]=db[n.dataset.delete].filter(x=>x.id!==n.dataset.id);if(n.dataset.delete==='radioChannels')for(const r of db.radioDevices)r.channelIds=(r.channelIds||[]).filter(cid=>cid!==n.dataset.id);save();render()}return}const a=n.dataset.action;if(!a)return;if(a.startsWith('deletetire:')||a.startsWith('deleterain:')){const key=a.startsWith('deletetire:')?'tires':'rainfall';if(confirm('¿Eliminar este registro?')){db[key]=db[key].filter(x=>x.id!==a.split(':')[1]);save();render()}return}if(a.startsWith('removealert:')){if(confirm('¿Eliminar alerta?')){db.maintenanceAlerts=db.maintenanceAlerts.filter(x=>x.id!==a.slice(12));save();render()}return}if(a.startsWith('removelocation:')){if(confirm('¿Eliminar ubicación?')){db.fieldLocations=db.fieldLocations.filter(x=>x.id!==a.slice(15));save();render()}return}if(a.startsWith('radioedit:')){selected=a.slice('radioedit:'.length);go('radioedit');return}if(a.startsWith('liquidprint:')){liquidationPrint(a.slice(12));return}if(a.startsWith('editmachine:')){selected=a.slice(12);go('editmachine');return}if(a.startsWith('deletemachine:')){const i=Number(a.slice(14)),name=db.machines[i];if(name&&confirm('¿Eliminar '+name+' del catálogo? Los registros históricos se conservarán.')){db.machines.splice(i,1);db.machineDetails=db.machineDetails.filter(m=>m.name!==name);save();render()}return}if(a.startsWith('deleteworker:')){const wid=a.slice('deleteworker:'.length),w=worker(wid);if(!w)return;const assigned=db.jobs.filter(j=>j.staff?.[wid]!==undefined).length,payments=db.payments.filter(p=>p.workerId===wid).length;const warning=`¿Eliminar a ${w.name}?\n\nTrabajos asignados: ${assigned}. Pagos/adelantos registrados: ${payments}.\n\nSe eliminará al empleado de los trabajos y también su historial de pagos. Los importes de liquidación y rentabilidad de esos trabajos se recalcularán. Esta acción no se puede deshacer. Recomendamos descargar una copia JSON antes.`;if(confirm(warning)){db.workers=db.workers.filter(x=>x.id!==wid);db.payments=db.payments.filter(x=>x.workerId!==wid);for(const j of db.jobs){if(j.staff)delete j.staff[wid]}save();render()}return}if(a.startsWith('deletejob:')){const jid=a.slice(10),j=job(jid);if(!j)return;if(confirm('¿Eliminar definitivamente el trabajo '+j.name+' y todos sus registros asociados (hectáreas, gasoil, gastos, cobros y pagos asignados)? Esta acción no se puede deshacer. Hacé una copia de seguridad antes de continuar.')){db.jobs=db.jobs.filter(x=>x.id!==jid);for(const k of ['hectares','fuelUse','expenses','receipts','payments'])db[k]=db[k].filter(x=>x.jobId!==jid);if(selected===jid)selected=null;page='jobs';save();render()}return}if(a.startsWith('job:')){selected=a.slice(4);jobTab='overview';go('job')}else if(a.startsWith('editjob:')){selected=a.slice(8);go('editjob')}else if(a.startsWith('editworker:')){selected=a.slice(11);go('editworker')}else if(a.startsWith('print:'))printJob(a.slice(6));else if(a==='printall')printAll();else if(a.startsWith('quoteprint:'))printQuote(a.slice(11));else if(a.startsWith('quotework:'))quoteToJob(a.slice(10));else if(a.startsWith('stock:')){selected=a.slice(6);go('stockuse')} else if(a==='backup')backup();else if(a==='restore'){if(!$('#restoreFile'))go('backups');$('#restoreFile')?.click();}else if(a==='csv')csv();else go(a)});
document.addEventListener('submit',e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const d=Object.fromEntries(new FormData(f).entries());try{switch(f.dataset.form){case 'tire':{if(!d.machine||!d.position?.trim())throw Error('Completá máquina y posición');if(num(d.currentHours)<num(d.startHours))throw Error('Las horas actuales no pueden ser menores que las iniciales');db.tires.push({id:id(),machine:d.machine,position:d.position.trim(),size:d.size||'',brand:d.brand||'',installed:d.installed,startHours:num(d.startHours),currentHours:num(d.currentHours),cost:num(d.cost),notes:d.notes||''});page='tires';break}case 'rain':{if(!d.field?.trim()||!d.date||d.mm===''||!Number.isFinite(Number(d.mm))||Number(d.mm)<0)throw Error('Completá campo, fecha y milímetros válidos');db.rainfall.push({id:id(),field:d.field.trim(),date:d.date,mm:Number(d.mm),notes:d.notes||''});page='rainfall';break}case 'maintenancealert':{if(!d.detail?.trim()||!d.machine)throw Error('Completá máquina y descripción');if(num(d.nextHours)<=0&&!d.dueDate)throw Error('Indicá horas de aviso o fecha');db.maintenanceAlerts.push({id:id(),machine:d.machine,detail:d.detail.trim(),currentHours:num(d.currentHours),nextHours:num(d.nextHours),dueDate:d.dueDate||''});page='maintalerts';break}case 'fieldlocation':{const lat=Number(d.lat),lng=Number(d.lng);if(!d.name?.trim()||d.lat===''||d.lng===''||!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)throw Error('Ingresá nombre y coordenadas válidas');db.fieldLocations.push({id:id(),name:d.name.trim(),lat,lng,address:d.address||''});page='locations';break}case 'company':{db.company={name:d.name||'',owner:d.owner||'',cuit:d.cuit||'',phone:d.phone||'',city:d.city||'',address:d.address||''};page='companysettings';break}case 'radiochannel':{if(!d.name.trim()||num(d.rx)<=0||num(d.tx)<=0||num(d.rx)>1000||num(d.tx)>1000)throw Error('Indicá nombre y frecuencias válidas en MHz');db.radioChannels.push({id:id(),name:d.name.trim(),rx:num(d.rx),tx:num(d.tx),tone:d.tone||'',note:d.note||''});page='radios';break}case 'radiodevice':{if(!d.brand.trim()||!d.model.trim())throw Error('Ingresá marca y modelo');db.radioDevices.push({id:id(),brand:d.brand.trim(),model:d.model.trim(),alias:d.alias||'',machine:d.machine||'',operator:d.operator||'',serial:d.serial||'',channelIds:[]});page='radios';break}case 'radioedit':{const x=db.radioDevices.find(r=>r.id===d.id);if(!x)throw Error('Equipo no encontrado');if(!d.brand.trim()||!d.model.trim())throw Error('Ingresá marca y modelo');Object.assign(x,{brand:d.brand.trim(),model:d.model.trim(),alias:d.alias||'',machine:d.machine||'',operator:d.operator||'',serial:d.serial||'',channelIds:db.radioChannels.filter(c=>d['channel_'+c.id]).map(c=>c.id)});page='radios';break}case 'job':{if(!d.name.trim())throw Error('Indicá un campo');const staff={};for(const w of db.workers)if(d['staff_'+w.id])staff[w.id]=num(d['pct_'+w.id]);const machines=db.machines.filter((m,i)=>d['machine_'+i]);const old=job(d.id);const j={id:old?.id||id(),name:d.name.trim(),client:d.client.trim(),labor:d.labor.trim(),date:d.date,price:num(d.price),vat:num(d.vat),status:d.status,staff,machines,plannedHa:num(d.plannedHa),finalHa:old?.finalHa??null};if(old)Object.assign(old,j);else db.jobs.push(j);selected=j.id;jobTab='overview';page='job';break}case 'newworker':{if(!d.name?.trim())throw Error('Ingresá el nombre');db.workers.push({id:id(),name:d.name.trim(),pct:num(d.pct)});page='workers';break}case 'worker':{const w=worker(d.id);w.name=d.name.trim();w.pct=num(d.pct);page='workers';break}case 'machine':{const name=d.name.trim();if(!name)throw Error('Ingresá un nombre');if(db.machines.includes(name))throw Error('Ya existe una máquina con ese nombre');db.machines.push(name);db.machineDetails.push({name,type:d.type,color:d.color});page='machines';break}case 'machineedit':{const name=d.name.trim(),old=d.old;if(!name)throw Error('Ingresá un nombre');if(name!==old&&db.machines.includes(name))throw Error('Ya existe ese nombre');const idx=db.machines.indexOf(old);if(idx<0)throw Error('Máquina no encontrada');db.machines[idx]=name;db.machineDetails=db.machineDetails.filter(m=>m.name!==old);db.machineDetails.push({name,type:d.type,color:d.color});if(old!==name){for(const j of db.jobs)j.machines=(j.machines||[]).map(m=>m===old?name:m);for(const k of ['fuelLoads','maintenance','plans'])for(const x of db[k])if(x.machine===old)x.machine=name;for(const x of db.inventory)if(x.machine===old)x.machine=name}page='machines';break}case 'finalha':{const j=job(selected);j.finalHa=d.finalHa===''?null:num(d.finalHa);break}case 'hectares':validateAmount(num(d.ha),'Hectáreas');db.hectares.push({id:id(),jobId:selected,date:d.date,ha:num(d.ha)});break;case 'fuelload':validateAmount(num(d.liters),'Litros');validateAmount(num(d.price),'Precio');db.fuelLoads.push({id:id(),date:d.date,machine:d.machine,liters:num(d.liters),price:num(d.price)});break;case 'fueluse':case 'fueluseglobal':{validateAmount(num(d.liters),'Litros');if(d.source!=='client'&&num(d.liters)>fuelAvailable()+0.00001)throw Error('No hay suficientes litros cargados sin asignar');if(d.source!=='client'&&!fuelLoaded())throw Error('Primero registrá una carga');if(d.source==='client'&&d.deduct==='yes'&&num(d.clientPrice)<=0)throw Error('Indicá el precio por litro para descontarlo');db.fuelUse.push({id:id(),jobId:f.dataset.form==='fueluse'?selected:d.jobId,date:d.date,liters:num(d.liters),source:d.source==='client'?'client':'owner',deduct:d.source==='client'&&d.deduct==='yes',unitPrice:d.source==='client'?num(d.clientPrice):averageFuel()});break}case 'expense':validateAmount(num(d.amount),'Importe');if(d.scope==='job'&&!d.jobId)throw Error('Primero creá un trabajo');db.expenses.push({id:id(),jobId:d.scope==='job'?d.jobId:null,category:d.category,date:d.date,detail:d.detail||'',amount:num(d.amount)});break;case 'payment':validateAmount(num(d.amount),'Importe');if(d.scope==='job'&&!d.jobId)throw Error('Primero creá un trabajo');db.payments.push({id:id(),workerId:d.workerId,jobId:d.scope==='job'?d.jobId:null,type:d.type,date:d.date,amount:num(d.amount)});break;case 'maintenance':db.maintenance.push({id:id(),machine:d.machine,date:d.date,hours:num(d.hours),detail:d.detail,amount:num(d.amount)});break;case 'plan':db.plans.push({id:id(),name:d.name, labor:d.labor,date:d.date,machine:d.machine,hectares:num(d.hectares)});break;case 'quote':{if(!d.issuer.trim()||!d.client.trim()||!d.labor.trim())throw Error('Completá emisor, cliente y labor');validateAmount(num(d.hectares),'Hectáreas');validateAmount(num(d.price),'Precio');db.quotes.push({id:id(),issuer:d.issuer.trim(),client:d.client.trim(),field:d.field||'',labor:d.labor.trim(),date:d.date,expiry:d.expiry,hectares:num(d.hectares),price:num(d.price),vat:num(d.vat),notes:d.notes||'',status:'Pendiente'});page='quotes';break}case 'item':{if(!d.name.trim())throw Error('Indicá el producto');db.inventory.push({id:id(),category:d.category,unit:d.category==='Aceite'?'L':d.category==='Grasa'?'kg':'unidades',name:d.name.trim(),code:d.code||'',machine:d.machine||'',supplier:d.supplier||'',qty:num(d.qty),min:num(d.min),cost:num(d.cost)});page='inventory';break}case 'stockuse':{const x=db.inventory.find(x=>x.id===d.id);validateAmount(num(d.qty),'Cantidad');if(!x||num(d.qty)>num(x.qty))throw Error('Stock insuficiente');x.qty-=num(d.qty);if(d.machine)db.maintenance.push({id:id(),machine:d.machine,date:today(),hours:0,detail:(d.detail||'Consumo de inventario')+' · '+x.name+' x '+d.qty+' '+(x.unit||'unidades'),amount:num(d.qty)*num(x.cost)});page='inventory';break}case 'alert':{if(!d.detail.trim())throw Error('Indicá el motivo');db.alerts.push({id:id(),detail:d.detail,date:d.date});page='alerts';break}case 'receipt':validateAmount(num(d.amount),'Importe');db.receipts.push({id:id(),jobId:d.jobId,type:d.type,date:d.date,amount:num(d.amount),note:d.note||''});break;}save();render();alert('Registro guardado.')}catch(err){alert(err.message)}});
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}function backup(){download('SERVICIOS_respaldo_'+today()+'.json',JSON.stringify({app:'SERVICIOS',version:1,exportedAt:new Date().toISOString(),data:db},null,2),'application/json')}document.addEventListener('change',async e=>{if(e.target.id!=='restoreFile')return;const file=e.target.files[0];if(!file)return;try{const obj=JSON.parse(await file.text());const data=obj.data;if(!data||!Array.isArray(data.jobs)||!Array.isArray(data.workers)||!Array.isArray(data.fuelLoads))throw Error('Archivo de respaldo no válido');if(!confirm('Esta acción reemplazará TODOS los datos actuales. ¿Continuar?'))return;db=data;for(const [k,v] of Object.entries(initial()))if(!Array.isArray(db[k]))db[k]=v;if(!db.company||typeof db.company!=='object')db.company={};save();go('home');alert('Respaldo restaurado.')}catch(err){alert('No se pudo importar: '+err.message)}finally{e.target.value=''}});
function csv(){const rows=[['Tipo','Fecha','Campo','Descripción','Cantidad','Importe ARS']];for(const j of db.jobs)rows.push(['Trabajo',j.date,j.name,j.labor,ha(j),revenue(j)]);for(const x of db.hectares)rows.push(['Hectáreas',x.date,jobName(x.jobId),'Jornada',x.ha,'']);for(const x of db.fuelLoads)rows.push(['Carga gasoil',x.date,'',x.machine,x.liters,x.liters*x.price]);for(const x of db.fuelUse)rows.push(['Consumo gasoil',x.date,jobName(x.jobId),'Consumo real',x.liters,x.liters*x.unitPrice]);for(const x of db.expenses)rows.push(['Gasto',x.date,x.jobId?jobName(x.jobId):'General',x.category+' '+x.detail,'',x.amount]);for(const x of db.receipts)rows.push(['Cobro',x.date,jobName(x.jobId),x.type+' '+x.note,'',x.amount]);for(const x of db.payments)rows.push(['Pago empleado',x.date,x.jobId?jobName(x.jobId):'General',workerName(x.workerId)+' '+x.type,'',x.amount]);const csvText='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');download('SERVICIOS_'+today()+'.csv',csvText,'text/csv;charset=utf-8')}
function printHeader(t){return `<h1>SERVICIOS</h1><p>${esc(t)} · ${today()}</p><hr>`}function printJob(jid){const j=job(jid);if(!j)return;$('#printArea').innerHTML=printHeader('Informe del trabajo')+`<h2>${esc(j.name)}</h2><p>Cliente: ${esc(j.client)} | Labor: ${esc(j.labor)} | Estado: ${j.status==='done'?'Terminado':'Activo'}</p><p>Equipos: ${esc((j.machines||[]).join(', '))}</p><table style="width:100%;border-collapse:collapse">${[['Hectáreas',fmt(ha(j))],['Precio por ha',money(j.price)],['Facturación sin IVA',money(revenue(j))],['IVA '+j.vat+'%',money(vat(j))],['Total a cobrar',money(invoice(j))],['Cobros',money(received(j))],['Gasoil descontado del saldo',money(fuelDeduction(j))],['Saldo cliente',money(balance(j))],['Gasoil',money(fuelCost(j))],['Sueldos devengados',money(staffCost(j))],['Otros gastos',money(jobExpenses(j))],['Ganancia estimada sin IVA',money(profit(j))]].map(([k,v])=>`<tr><td style="padding:7px;border-bottom:1px solid #ddd">${k}</td><td style="text-align:right;border-bottom:1px solid #ddd">${v}</td></tr>`).join('')}</table><h3>Empleados</h3>${db.workers.filter(w=>j.staff?.[w.id]!==undefined).map(w=>`<p>${esc(w.name)}: ${fmt(j.staff[w.id])}% — ${money(earnings(j,w.id))}</p>`).join('')}<p style="font-size:12px">Resultado estimado antes de gastos generales e impuestos sobre la renta. IVA separado del ingreso operativo.</p>`;window.print()}
function printAll(){$('#printArea').innerHTML=printHeader('Informe general')+`<p>Trabajos: ${db.jobs.length} | Hectáreas: ${fmt(db.jobs.reduce((s,j)=>s+ha(j),0))}</p><h2>Resultados</h2>${db.jobs.map(j=>`<p><b>${esc(j.name)}</b>: ${fmt(ha(j))} ha · Facturación ${money(revenue(j))} · Ganancia ${money(profit(j))} · Pendiente ${money(balance(j))}</p>`).join('')}<hr><p>Gastos generales: ${money(sum(db.expenses.filter(x=>!x.jobId),'amount'))}</p><p>Ganancia estimada empresa: ${money(db.jobs.reduce((s,j)=>s+profit(j),0)-sum(db.expenses.filter(x=>!x.jobId),'amount'))}</p>`;window.print()}
window.serviciosStart=function(data){db=data||initial();for(const [k,v] of Object.entries(initial()))if(!Array.isArray(db[k]))db[k]=v;if(!Array.isArray(db.machineDetails))db.machineDetails=[];if(!db.company||typeof db.company!=='object')db.company={};page='home';render()};

// Personalización visual: no modifica los registros operativos.
document.addEventListener('click',function(e){const b=e.target.closest('.color-choice');if(b){e.preventDefault();window.setServiciosColor(b.dataset.color);const pick=document.getElementById('customAccent');if(pick)pick.value=b.dataset.color;const status=document.getElementById('accentStatus');if(status)status.textContent='Color aplicado: '+b.dataset.color;}});
document.addEventListener('input',function(e){if(e.target.id==='customAccent'){window.setServiciosColor(e.target.value);const status=document.getElementById('accentStatus');if(status)status.textContent='Color aplicado: '+e.target.value;}});


// Herramientas v19. No cambian las claves ni el esquema de registros previos.
function tirePressurePanel(){return `<div class="card"><h3>📋 Guía de presiones por fabricante</h3><p class="muted">La presión NO depende solamente de la medida: verificá marca, modelo exacto, carga por rueda, velocidad, uso en campo/ruta y montaje simple o dual. No usar valores genéricos como presión recomendada.</p><label>Medida del neumático para buscar en el catálogo</label><input id="tireSizeSearch" placeholder="Ej. 18.4R30 o 420/85R34"><div class="flex" style="margin-top:12px"><button type="button" onclick="window.open('https://business.michelinman.com/help-advice/tools/agropressure','_blank')">Michelin AgroPressure ↗</button><button type="button" onclick="window.open('https://www.trelleborg-tires.com/es-ar/trelleborg-professional-centre/soporte-tecnico','_blank')">Trelleborg tablas ↗</button></div><p class="muted">Los enlaces oficiales requieren internet. Guardá la presión determinada para tu neumático en las observaciones del registro, indicando carga y velocidad.</p></div>`}

function metricDecimalPanel(){return title('📐 Sistema métrico decimal','Conversión de unidades para el campo y el taller')+`<div class="card"><h3>Convertidor de longitud</h3><label>Valor</label><input id="metricValue" type="number" step="any" value="1" oninput="updateMetricDecimal()"><label>Unidad de origen</label><select id="metricUnit" onchange="updateMetricDecimal()"><option value="0.001">Milímetros (mm)</option><option value="0.01">Centímetros (cm)</option><option value="0.1">Decímetros (dm)</option><option value="1" selected>Metros (m)</option><option value="10">Decámetros (dam)</option><option value="100">Hectómetros (hm)</option><option value="1000">Kilómetros (km)</option></select><div id="metricResults" class="notice"></div></div><div class="card"><h3>Tabla de equivalencias</h3><div style="overflow-x:auto"><table style="width:100%"><thead><tr><th>Unidad</th><th>Símbolo</th><th>En metros</th></tr></thead><tbody>${[['Kilómetro','km','1.000'],['Hectómetro','hm','100'],['Decámetro','dam','10'],['Metro','m','1'],['Decímetro','dm','0,1'],['Centímetro','cm','0,01'],['Milímetro','mm','0,001']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h3>Superficie, volumen y masa</h3><p><b>Superficie:</b> 1 ha = 10.000 m²; 1 km² = 100 ha; 1 m² = 10.000 cm².</p><p><b>Volumen:</b> 1 m³ = 1.000 L; 1 L = 1.000 mL; 1 cm³ = 1 mL.</p><p><b>Masa:</b> 1 t = 1.000 kg; 1 kg = 1.000 g; 1 g = 1.000 mg.</p><p class="muted">Longitud cambia de 10 en 10, superficie de 100 en 100 y volumen de 1.000 en 1.000 por cada salto de prefijo.</p></div>`}
function updateMetricDecimal(){const input=document.getElementById('metricValue'),unit=document.getElementById('metricUnit'),out=document.getElementById('metricResults');if(!input||!unit||!out)return;const n=Number(input.value)*Number(unit.value);const units=[['km',1000],['hm',100],['dam',10],['m',1],['dm',.1],['cm',.01],['mm',.001]];out.innerHTML=Number.isFinite(n)?units.map(([label,f])=>`<div class="row"><span>${label}</span><b>${(n/f).toLocaleString('es-AR',{maximumFractionDigits:8})}</b></div>`).join(''):'Ingresá un número válido.'}
